function formatItemTypeText(type: string): string {
	if (ITEM_MAP[type]) return ITEM_MAP[type];
	if (type.startsWith('all ') && type.endsWith(' containers')) {
		return type.replace('all ', '全部 ').replace(' containers', ' 个容器');
	}
	if (type.includes('stopped container')) {
		return type.replace('stopped container', '个已停止的容器').replace('s', '');
	}
	if (type.includes('running container')) {
		return type.replace('running container', '个运行中的容器').replace('s', '');
	}
	if (type.includes('paused container')) {
		return type.replace('paused container', '个已暂停的容器').replace('s', '');
	}
	if (type.includes('container')) {
		return type.replace('container', '个容器').replace('s', '');
	}
	if (type.includes('network')) {
		return type.replace('network', '个网络').replace('s', '');
	}
	if (type.includes('volume')) {
		return type.replace('volume', '个存储卷').replace('s', '');
	}
	return type;
}

